using NUnit.Framework;using UnityEngine;using LestingCraft.Gameplay;using LestingCraft.Story;using LestingCraft.World;
namespace LestingCraft.Tests
{
 public sealed class ChapterOneTests
 {
  [Test] public void LeftHandTransfersExactlyOneAndDeathKeepsIt(){CollectionAssert.Contains(LestingCraft.Presentation.ItemArtwork.AllIds,148);var inv=new Inventory();inv.Add(148,4);Assert.IsTrue(inv.ToggleOffhand());Assert.AreEqual(3,inv.Count(148));Assert.AreEqual(1,inv.offhand.count);Assert.AreEqual(22,inv.ExtraStacks().Length);Assert.AreEqual(148,inv.Clone().offhand.item);Assert.IsTrue(inv.ToggleOffhand());Assert.AreEqual(4,inv.Count(148));}
  [Test] public void CounterweightsAndRunesAreDifferentMechanisms(){var s=new StoryState{stage=4};Assert.IsFalse(StoryRules.Act(s,"village",0,10000,0));Assert.IsTrue(StoryRules.Act(s,"weight",0,10000,0));Assert.IsFalse(s.bridgeSolved);Assert.IsTrue(StoryRules.Act(s,"weight",2,10000,0));Assert.IsTrue(s.bridgeSolved);Assert.IsTrue(StoryRules.Act(s,"village",0,10000,18));s.stage=8;s.line=-1;StoryRules.Act(s,"rune",0,10000,0);Assert.AreEqual(0,s.runes);foreach(int rune in new[]{2,0,1})Assert.IsTrue(StoryRules.Act(s,"rune",rune,10000,0));Assert.AreEqual(9,s.stage);Assert.AreEqual(-1,s.line);}
  [Test] public void GuardianNeedsThreeFiresAndResetsAtHalfHealth(){var s=new StoryState{stage=11,bossHealth=180};Assert.IsFalse(StoryRules.Act(s,"hit",0,10000,0));for(int i=0;i<3;i++)Assert.IsTrue(StoryRules.Act(s,"pylon",i,10000,0));for(int i=0;i<12;i++)StoryRules.Act(s,"hit",0,11000,0);Assert.AreEqual(1,s.bossPhase);Assert.AreEqual(0,s.pylons);Assert.Greater(s.bossHealth,0);Assert.IsFalse(StoryRules.Act(s,"hit",0,11000,0));for(int i=0;i<3;i++)StoryRules.Act(s,"pylon",i,12000,0);for(int i=0;i<12;i++)StoryRules.Act(s,"hit",0,13000,0);Assert.AreEqual(12,s.stage);Assert.AreEqual(8,s.rewards);Assert.IsTrue(StoryRules.Tick(s,30000));Assert.AreEqual(13,s.stage);}
  [Test] public void NewLandmarksNeverMutateLegacySamplers(){int f=StoryWorld.Floor(2506);Assert.AreEqual(36,TerrainGenerator.SampleContent(-32,f,-32,2506,Dimension.Lestingia,4));for(int x=-48;x<64;x+=7)for(int z=-48;z<64;z+=7){int h=TerrainGenerator.Height(x,z,2506,Dimension.Lestingia);Assert.AreEqual(NatureGenerator.Sample(x,h+1,z,2506),TerrainGenerator.SampleContent(x,h+1,z,2506,Dimension.Lestingia,3));Assert.AreEqual(TerrainGenerator.Sample(x,h,z,2506,Dimension.Lestingia),TerrainGenerator.SampleContent(x,h,z,2506,Dimension.Lestingia,1));}}
  [Test] public void ChapterResourcesAndTorchAreNativeAssets(){var content=JsonUtility.FromJson<StoryContent>(Resources.Load<TextAsset>("Story/ChapterOne").text);int count=0;foreach(var n in content.nodes)count+=n.lines.Length;Assert.GreaterOrEqual(count,74);GeneratedPresentationAssets.EnsureLoaded();Assert.IsNotNull(LestingCraft.Presentation.ItemArtwork.Get(148));Assert.IsNotNull(LestingCraft.Presentation.VoxelItemModels.MeshFor(148));}
 }
}
